const req=(v,l)=>{if(v==null||String(v).trim()==='')throw new TypeError(`${l} is required`);return String(v).trim()};
const positiveInt=(v,l)=>{const n=Number(v);if(!Number.isInteger(n)||n<1)throw new TypeError(`${l} must be a positive integer`);return n};
export function createApprovalRequest({id,subjectRef,requestedBy,steps=[],metadata={},createdAt=new Date().toISOString()}={}){if(!subjectRef?.kind||!subjectRef?.id)throw new TypeError('subjectRef kind and id are required');if(!steps.length)throw new TypeError('at least one approval step is required');const normalized=steps.map((s,i)=>{const approverIds=[...new Set((s.approverIds??[]).map(String))],minApprovals=positiveInt(s.minApprovals??1,'minApprovals');if(approverIds.length&&minApprovals>approverIds.length)throw new TypeError('minApprovals cannot exceed the approver allowlist');return Object.freeze({id:req(s.id??`step-${i+1}`,'step id'),approverIds:Object.freeze(approverIds),minApprovals,decisions:Object.freeze([])})});if(new Set(normalized.map(s=>s.id)).size!==normalized.length)throw new TypeError('approval step ids must be unique');return Object.freeze({id:req(id,'approval id'),subjectRef:Object.freeze({kind:req(subjectRef.kind,'subject kind'),id:req(subjectRef.id,'subject id')}),requestedBy:req(requestedBy,'requestedBy'),status:'pending',currentStepId:normalized[0].id,steps:Object.freeze(normalized),history:Object.freeze([]),metadata:Object.freeze({...metadata}),createdAt:new Date(createdAt).toISOString(),updatedAt:new Date(createdAt).toISOString()})}
function derive(steps){for(const step of steps){if(step.decisions.some(d=>d.decision==='rejected'))return{status:'rejected',currentStepId:step.id};const approvals=new Set(step.decisions.filter(d=>d.decision==='approved').map(d=>d.actorId)).size;if(approvals<step.minApprovals)return{status:'pending',currentStepId:step.id}}return{status:'approved',currentStepId:null}}
export function decideApproval(request,{stepId=request.currentStepId,actorId,decision,comment=null,at=new Date().toISOString()}={}){actorId=req(actorId,'actorId');if(request.status!=='pending')throw new Error('approval request is already closed');if(!['approved','rejected'].includes(decision))throw new TypeError('decision must be approved or rejected');if(stepId!==request.currentStepId)throw new Error('only current approval step can be decided');const steps=request.steps.map(step=>{if(step.id!==stepId)return step;if(step.approverIds.length&&!step.approverIds.includes(actorId))throw new Error('actor is not allowed for this approval step');if(step.decisions.some(d=>d.actorId===actorId))throw new Error('actor already decided this step');return Object.freeze({...step,decisions:Object.freeze([...step.decisions,Object.freeze({actorId,decision,comment:comment==null?null:String(comment),at:new Date(at).toISOString()})])})});const state=derive(steps);return Object.freeze({...request,...state,steps:Object.freeze(steps),history:Object.freeze([...request.history,{stepId,actorId,decision,at:new Date(at).toISOString()}]),updatedAt:new Date(at).toISOString()})}
export function canActorApprove(request,actorId){const step=request.steps.find(s=>s.id===request.currentStepId);return Boolean(request.status==='pending'&&step&&!step.decisions.some(d=>d.actorId===String(actorId))&&(!step.approverIds.length||step.approverIds.includes(String(actorId))))}
